["Node ex:ship must conform to one or more shapes in [ sh:property [ sh:datatype xsd:boolean ; sh:hasValue Literal("true" = True, datatype=xsd:boolean) ; sh:maxCount Literal("1", datatype=xsd:integer) ; sh:message Literal("When Chapter 11-1 applies, the voyage plan must be present.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path nltl:voyagePlanPresent ], [ sh:datatype xsd:boolean ; sh:hasValue Literal("true" = True, datatype=xsd:boolean) ; sh:maxCount Literal("1", datatype=xsd:integer) ; sh:message Literal("When Chapter 11-1 applies, the voyage plan must cover every intended voyage hazard.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path nltl:voyagePlanCoverage ], [ sh:datatype xsd:boolean ; sh:hasValue Literal("true" = True, datatype=xsd:boolean) ; sh:path nltl:polarCodeChapter11Dash1Applicable ], [ sh:datatype xsd:string ; sh:message Literal("Each intended voyage hazard must be recorded as a string.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path nltl:intendedVoyageHazard ] ; sh:sparql [ sh:message Literal("Every intended voyage hazard must have voyage-plan coverage equal to true when Chapter 11-1 applies.") ; sh:select Literal("
                    PREFIX nltl: <https://w3id.org/nltl/vocab#>
                    SELECT $this ?hazard
                    WHERE {
                        $this nltl:intendedVoyageHazard ?hazard .
                        FILTER NOT EXISTS {
                            $this nltl:voyagePlanCoverage true .
                        }
                    }
                ") ] ] , [ sh:property [ sh:datatype xsd:boolean ; sh:hasValue Literal("false" = False, datatype=xsd:boolean) ; sh:path nltl:polarCodeChapter11Dash1Applicable ] ]"]

